 const kpis=`<section class="dues-kpis" aria-label="${tx('Forderungsübersicht','Borç özeti','Charges overview')}"><article class="dues-kpi dues-kpi-primary"><span>${tx('Offener Betrag','Açık toplam','Outstanding balance')}</span><strong>${money(stats.outstanding)}</strong><small>${scope}</small></article><article class="dues-kpi"><span>${tx('Offene Posten','Açık kayıtlar','Open charges')}</span><strong>${stats.open}</strong><small>${stats.partial} ${tx('davon teilweise bezahlt','kısmen ödendi','partly paid')}</small></article><article class="dues-kpi"><span>${tx('Vollständig bezahlt','Tamamı ödenen','Paid in full')}</span><strong>${stats.settled}</strong><small>${tx('Erledigte Forderungen','Kapanan borç kayıtları','Settled charges')}</small></article></section>`;
