 const quick=canPrepare?`<section id="dues-create" class="card dues-create"><div class="dues-section-head"><div><span class="dues-overline">${tx('VERWALTUNG','YÖNETİM','MANAGEMENT')}</span><h2>${tx('Neue Buchung vorbereiten','Yeni tahakkuk hazırla','Prepare a new charge')}</h2><p>${tx('Hausgeld und besondere Forderungen werden getrennt vorbereitet. Die bisherigen Freigaberegeln bleiben bestehen.','Aidat ve diğer borçlar ayrı hazırlanır. Mevcut onay kuralları geçerlidir.','Prepare monthly dues and other charges separately. Existing approval rules still apply.')}</p></div></div><div class="dues-action-grid"><div class="dues-action"><span class="dues-action-icon" aria-hidden="true">▦</span><div><h3>${tx('Monatliches Hausgeld','Aylık aidat','Monthly dues')}</h3><p>${tx('Reguläre Aidat-Forderungen vorbereiten.','Düzenli aidat borçlarını hazırla.','Prepare regular monthly dues.')}</p></div>${button(tx('Hausgeld erstellen','Aidat oluştur','Create dues'),'monthly_v5','',true)}</div><div class="dues-action"><span class="dues-action-icon" aria-hidden="true">＋</span><div><h3>${tx('Weitere Forderung','Diğer borç','Other charge')}</h3><p>${tx('Einmalige Umlagen oder sonstige Posten erfassen.','Tek seferlik ek gider veya diğer borçları gir.','Prepare a one-time levy or another charge.')}</p></div>${button(tx('Forderung erfassen','Borç ekle','Add charge'),'batch_charge')}</div></div></section>`:'';
 const register=`<section id="dues-claims" class="card dues-register"><div class="dues-section-head"><div><span class="dues-overline">${tx('FORDERUNGEN','BORÇLAR','CHARGES')}</span><h2>${tx('Forderungen im Überblick','Borç kayıtları','Charge records')}</h2><p>${tx('Wohnung oder Namen suchen, nach Status filtern und Details direkt öffnen.','Daire veya kişi ara, duruma göre filtrele ve ayrıntıları aç.','Search an apartment or person, filter by status and open details.')}</p></div></div>${chargeBrowser(s,current,rows=>`<div data-charge-view="compact">${compactCharges(s,rows)}</div><div data-charge-view="detail" hidden>${charges(s,rows)}</div>`)}</section>`;
 const drafts=chargeDraftPanel(s);
 const draftSection=drafts?`<details class="card ledger-more dues-fold"><summary><strong>${tr('Forderungsentwürfe')}</strong><span class="muted">(${d.chargeDrafts?.length||0})</span></summary>${drafts}</details>`:'';
 const payments=`<details id="dues-payments" class="card ledger-more dues-fold"><summary><strong>${tx('Zugeordnete Zahlungen','Eşleştirilen ödemeler','Allocated payments')}</strong><span class="muted">${tx('Zahlungen zu Forderungen ansehen','Borçlara işlenen ödemeleri gör','See payments applied to charges')}</span></summary><p class="fine">${tx('Hier erscheinen Zahlungen, die einer Forderung zugeordnet wurden.','Burada borçlarla eşleştirilen ödemeler gösterilir.','Only payments allocated to charges are shown here.')}</p>${allocationTable(s)}</details>`;
 const previous=((resident||can(s,'finance')||d.managementRead)&&old.length)?`<details class="card ledger-more dues-fold"><summary><strong>${tr('Önceki sakinlerin borçları')}</strong><span class="muted">(${old.length} · ${money(oldStats.outstanding)})</span></summary><p class="fine">${tr('Yeni sakinin hesabına dahil edilmez.')}</p>${charges(s,old)}</details>`:'';
 const overpayments=credits.length?`<details class="card ledger-more dues-fold"><summary><strong>${tx('Noch nicht verrechnete Zahlungen','Henüz mahsup edilmemiş ödemeler','Unapplied payments')}</strong><span class="muted">(${credits.length})</span></summary><p class="fine">${tx('Bereits eingegangene Zahlungen, die noch keiner Forderung zugeordnet wurden. Vor dem Verrechnen bitte prüfen.','Bankaya gelmiş, ancak henüz bir borca eşleştirilmemiş ödemeler. Eşleştirmeden önce kontrol edin.','Payments received but not yet applied to a charge. Please verify before allocating.')}</p>${credits.map(c=>`<div class="contact-row"><span>${e(d.units.find(u=>u.id===c.unit_id)?.code||'')} ${can(s,'finance')?e(personName(d,c.person_id)):''} · <strong>${money(c.cents)}</strong></span>${can(s,'admin')?button(tr('Ayırmayı kaldır'),'void_credit',`data-id="${e(c.id)}"`):''}</div>`).join('')}</details>`:'';
